def get_four_direction_neighbors(x, y, grid):
    result = []
    if y > 0:
        result.append(((-1, 0), grid[y-1][x]))
    if y < rows - 1:
        result.append(((1, 0), grid[y+1][x]))
    if x > 0:
        result.append(((0, -1), grid[y][x-1]))
    if x < cols - 1:
        result.append(((0, 1), grid[y][x+1]))
    return result

