def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])
    result = [[grid[y][x] for x in range(cols)] for y in range(rows)]

    for y in range(rows):
        for x in range(cols):
            if grid[y][x] == 6:
                continue
            elif grid[y][x] == 8:
                has_left = (x > 0 and grid[y][x-1] == 6)
                has_right = (x < cols - 1 and grid[y][x+1] == 6)
                if has_left and has_right:
                    result[y][x] = 2
    return result
